class Solution:
    def twoSum(self, nums, target):
        index_of = {x: i for i, x in enumerate(nums)}
        for i, x in enumerate(nums):
            if x > target:  # 'pruning' that silently assumes non-negative numbers
                continue
            j = index_of.get(target - x)
            if j is not None and j != i:
                return [i, j]

